import json
demos = {
    "action": "request_demos"
}
print(json.dumps(demos))

# Analyze the demo pattern and generate expected output
# Input grid is 14x16 filled with 7
# Marked positions with their values
marked = {
    (7, 8): 6,
    (7, 11): 4,
    (8, 9): 6,
    (8, 10): 4,
    (9, 9): 8,
    (9, 10): 9,
    (10, 8): 8,
    (10, 11): 9,
}

def propagate_diagonal(value, start_r, start_c, directions, grid_w, grid_h):
    """Propagate value along four diagonal directions and return dict of (r,c) -> value"""
    result = {}
    for dr, dc in directions:
        r, c = start_r, start_c
        while 0 <= r < grid_h and 0 <= c < grid_w:
            result[(r, c)] = value
            r += dr
            c += dc
    return result

# Four diagonal directions
directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]  # up-left, up-right, down-left, down-right

result = {}
for (r, c), val in marked.items():
    prop = propagate_diagonal(val, r, c, directions, 16, 14)
    result.update(prop)

# Where there are conflicts (same cell has multiple values), rightmost wins (larger r, or same r larger c)
# Sort by (r descending, c descending) and apply
conflicts = {}
for (r, c), val in result.items():
    if (r, c) in conflicts:
        if val > conflicts[(r, c)]:
            conflicts[(r, c)] = val
        else:
            pass  # Keep original
    else:
        conflicts[(r, c)] = val

# Build expected output
expected = [[7]*16 for _ in range(14)]
for (r, c), val in conflicts.items():
    expected[r][c] = val

print("Expected output:")
for row in expected:
    print(' '.join(f'{v}' for v in row))

