import json

bg = 2
grid_h, grid_w = 14, 23

marked = {
    (2, 14): 8, (2, 17): 7, (3, 15): 8, (3, 16): 7,
    (4, 15): 5, (4, 16): 3, (5, 14): 5, (5, 17): 3,
}

chains = []

for val in sorted(marked.values()):
    positions = [(r,c) for (r,c),v in marked.items() if v == val]
    if len(positions) >= 2:
        # Find diagonally connected pair
        for i in range(len(positions)):
            for j in range(i+1, len(positions)):
                p1, p2 = positions[i], positions[j]
                if abs(p1[0]-p2[0]) == 1 and abs(p1[1]-p2[1]) == 1:
                    # Upper position to lower position
                    r1, c1, r2, c2 = p1[0], p1[1], p2[0], p2[1]
                    dr, dc = r2 - r1, c2 - c1  # Connection direction

                    # Chain starts from upper position and extends in same direction
                    chain = []
                    r, c = r1, c1
                    while 0 <= r < grid_h and 0 <= c < grid_w:
                        chain.append((r, c))
                        r += dr
                        c += dc
                    chains.append((chain, val))
                    print(f"Value {val}, pair {p1}-{p2}: {chain}")
                    break
        else:
            continue
        break

# Add chains to output
for chain, val in chains:
    for (r, c) in chain:
        output = [[bg] * grid_w for _ in range(grid_h)]
        for (r, c) in chain:
            if 0 <= r < grid_h and 0 <= c < grid_w:
                output[r][c] = val
        json.dumps({"action": "submit", "grid": output})

# Actually need to combine all chains with potential conflicts
output = [[bg] * grid_w for _ in range(grid_h)]
for chain, val in chains:
    for (r, c) in chain:
        if 0 <= r < grid_h and 0 <= c < grid_w:
            output[r][c] = val

print("\nFinal grid:")
for row in output:
    print(' '.join(str(v) for v in row))

